const r = await tools.pwsh({
  description: "查看 mdcg 数据与 openviking 数据存储位置",
  command: `
Write-Host '--- mdcg data ---'
Get-ChildItem "$env:DSH_HOME\\.dsh-memory\\data\\mdcg" -Recurse -Depth 1 | Select-Object FullName, Length | Out-String
Write-Host '--- storages ---'
Get-ChildItem "$env:DSH_HOME\\storages" | Select-Object Name | Out-String
Write-Host '--- openviking storage detail ---'
Get-ChildItem "$env:DSH_HOME\\storages" -Recurse -Depth 2 -ErrorAction SilentlyContinue | Select-Object FullName | Out-String
`
});
console.log(r.stdout);
